"""Copula mechanism layer.

Implements `copula_mechanism` backed by a Gaussian copula using only
``math`` + ``numpy`` (no extra dependencies), with automatic delegation
to ``pyvinecopulib`` when that package is installed for the full
vinecopulib bivariate family set. See SPEC.md section 4.1.

Design notes
------------
* ``variables[0]`` is the **child** (the feature generated by the
  mechanism); ``variables[1:]`` are the **parents**.  This must match
  the ``add_dependency(parents=variables[1:], child=variables[0], ...)``
  call.
* ``fit_data`` is required in v1: the copula is estimated from observed
  data via rank-based pseudo-observations.
* The numpy Gaussian copula:
  - Normal CDF  Φ  via ``math.erf``
  - Normal PPF  Φ⁻¹ via Peter Acklam's rational approximation + Newton
    polish (absolute error < 1e-9)
  - Empirical pseudo-observations (mid-rank) per variable
  - Conditional normal from pre-solved correlation partition
"""

from __future__ import annotations

import math
import warnings
from typing import Any, Optional, Sequence

import numpy as np
import pandas as pd

from .mechanism import Mechanism

# ---------------------------------------------------------------------------
# Normal CDF / PPF (stdlib + numpy only)
# ---------------------------------------------------------------------------

def _norm_cdf(x: float) -> float:
    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))


def _norm_ppf(p: float) -> float:
    """Inverse standard normal CDF (Acklam rational approx + Newton polish)."""
    p = float(np.clip(p, 1e-12, 1 - 1e-12))
    a = [-3.969683028665376e+01,  2.209460984245205e+02,
         -2.759285104469687e+02,  1.383577518672690e+02,
         -3.066479806614716e+01,  2.506628277459239e+00]
    b = [-5.447609879822406e+01,  1.615858368580409e+02,
         -1.556989798598866e+02,  6.680131188771972e+01,
         -1.328068155288572e+01]
    c = [-7.784894002430293e-03, -3.223964580411365e-01,
         -2.400758277161838e+00, -2.549732539343734e+00,
          4.374664141464968e+00,  2.938163982698783e+00]
    d = [ 7.784695709041462e-03,  3.224671290700398e-01,
          2.445134137142996e+00,  3.754408661907416e+00]
    p_lo, p_hi = 0.02425, 1 - 0.02425
    if p < p_lo:
        q = math.sqrt(-2 * math.log(p))
        x0 = (((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5]) / \
              ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1)
    elif p <= p_hi:
        q = p - 0.5; r = q*q
        x0 = (((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r+a[5])*q / \
              (((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r+1)
    else:
        q = math.sqrt(-2*math.log(1 - p))
        x0 = -(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5]) / \
               ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1)
    # Two Newton steps for < 1e-9 absolute error
    for _ in range(2):
        phi = math.exp(-0.5*x0*x0) / math.sqrt(2*math.pi)
        if phi < 1e-300:
            break
        x0 -= (_norm_cdf(x0) - p) / phi
    return x0


# ---------------------------------------------------------------------------
# Empirical CDF / quantile helpers
# ---------------------------------------------------------------------------

def _build_ecdf(values: np.ndarray):
    n = len(values)
    sorted_vals = np.sort(values)
    cdf_u = (np.arange(n) + 0.5) / n      # mid-rank pseudo-obs
    return sorted_vals, cdf_u


def _ecdf_transform(sv: np.ndarray, cu: np.ndarray, x: float) -> float:
    return float(np.interp(x, sv, cu, left=cu[0], right=cu[-1]))


def _ecdf_quantile(sv: np.ndarray, cu: np.ndarray, u: float) -> float:
    return float(np.interp(float(np.clip(u, cu[0], cu[-1])), cu, sv))


# ---------------------------------------------------------------------------
# Gaussian copula fit
# ---------------------------------------------------------------------------

def _fit_gaussian_copula(
    child: str,
    parents: list[str],
    fit_data: pd.DataFrame,
    nominal_handling: str,
) -> dict:
    variables = [child] + parents

    # Classify variable types
    var_types: dict[str, str] = {}
    levels: dict[str, list] = {}
    for v in variables:
        col = fit_data[v]
        if isinstance(col.dtype, pd.CategoricalDtype):
            if col.dtype.ordered:
                var_types[v] = "ordinal"
                levels[v] = list(col.cat.categories)
            else:
                if nominal_handling == "regression":
                    raise ValueError(
                        f"Variable '{v}' is nominal categorical. "
                        "Set nominal_handling='arbitrary_order' to include "
                        "it in the copula (with a warning), or exclude it "
                        "from `variables` and use a section-4 mechanism."
                    )
                warnings.warn(
                    f"Variable '{v}' is nominal categorical; included in "
                    "the Gaussian copula under an arbitrary level order.",
                    UserWarning, stacklevel=4,
                )
                var_types[v] = "categorical"
                levels[v] = list(col.cat.categories)
        else:
            var_types[v] = "continuous"

    # Raw numeric encoding (ordinal/categorical → integer codes)
    raw: dict[str, np.ndarray] = {}
    for v in variables:
        col = fit_data[v]
        if var_types[v] in ("ordinal", "categorical"):
            raw[v] = col.cat.codes.to_numpy(dtype=float)
        else:
            raw[v] = col.to_numpy(dtype=float)

    # Empirical CDF tables + normal scores (rank-based pseudo-obs)
    sorted_vals: dict[str, np.ndarray] = {}
    cdf_u_map: dict[str, np.ndarray] = {}
    normal_scores: list[np.ndarray] = []
    n = len(fit_data)
    for v in variables:
        sv, cu = _build_ecdf(raw[v])
        sorted_vals[v] = sv
        cdf_u_map[v] = cu
        # Re-rank the raw column to get its pseudo-obs, then normal-score it
        ranks = np.argsort(np.argsort(raw[v], kind="stable"), kind="stable")
        zv = np.array([_norm_ppf((r + 0.5) / n) for r in ranks])
        normal_scores.append(zv)

    Corr = np.corrcoef(np.column_stack(normal_scores).T)   # (d, d)

    # Pre-solve conditional Gaussian coefficients
    if len(parents) == 0:
        mu_coefs = np.zeros(0)
        var_cond = 1.0
    else:
        Corr_pp = Corr[1:, 1:] + 1e-8 * np.eye(len(parents))
        Corr_cp = Corr[0, 1:]
        try:
            A = np.linalg.solve(Corr_pp, Corr_cp)
        except np.linalg.LinAlgError:
            A = np.linalg.lstsq(Corr_pp, Corr_cp, rcond=None)[0]
        mu_coefs = A
        var_cond = float(max(1e-8, 1.0 - float(Corr_cp.dot(A))))

    return {
        "child": child, "parents": parents,
        "var_types": var_types, "levels": levels,
        "sorted_vals": sorted_vals, "cdf_u": cdf_u_map,
        "mu_coefs": mu_coefs, "var_cond": var_cond,
    }


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def copula_mechanism(
    variables: Sequence[str],
    family: str = "auto",
    marginals: str = "auto",
    nominal_handling: str = "regression",
    fit_data: Optional[pd.DataFrame] = None,
) -> Mechanism:
    """Copula-based dependency mechanism.

    ``variables[0]`` is the **child** (generated feature);
    ``variables[1:]`` are the **parents**.  Match the
    ``add_dependency(parents=variables[1:], child=variables[0], ...)``
    call accordingly.

    Parameters
    ----------
    variables:
        ``[child_name, parent1_name, ...]``.
    family:
        ``"auto"`` or ``"gaussian"`` uses the built-in numpy Gaussian
        copula (no extra dependencies required). Any other family
        requires ``pyvinecopulib`` (``pip install pyvinecopulib``).
    marginals:
        ``"auto"`` = empirical CDF (rank-based) for all variables.
    nominal_handling:
        ``"regression"`` (default): raises if a nominal categorical
        variable appears in ``variables``.
        ``"arbitrary_order"``: includes with a warning.
    fit_data:
        ``pandas.DataFrame`` with all ``variables`` columns.  Required
        in v1.

    Returns
    -------
    Mechanism
        Not JSON-serializable (``spec=None``) since it carries a fitted
        closure.
    """
    if fit_data is None:
        raise ValueError("`fit_data` is required (estimation-free "
                         "specification is not yet implemented).")
    variables = list(variables)
    if len(variables) < 1:
        raise ValueError("`variables` must have at least 1 element.")

    child = variables[0]
    parents = variables[1:]
    effective_family = "gaussian" if family in ("auto", "gaussian") else family.lower()

    if effective_family != "gaussian":
        try:
            import pyvinecopulib  # noqa: F401
        except ImportError:
            raise ImportError(
                f"family={family!r} requires pyvinecopulib: "
                "pip install pyvinecopulib. "
                "Use family='gaussian' for the built-in numpy fallback."
            )
        raise NotImplementedError(
            "pyvinecopulib delegation is not yet wired up. "
            "Use family='gaussian' or implement a custom wrapper via "
            "register_mechanism()."
        )

    model = _fit_gaussian_copula(child, parents, fit_data, nominal_handling)
    sv = model["sorted_vals"]
    cu = model["cdf_u"]
    vt = model["var_types"]
    lvl = model["levels"]
    mu_coefs = model["mu_coefs"]
    var_cond = model["var_cond"]
    sd_cond = math.sqrt(var_cond)

    def fn(parent_values: dict, rng: np.random.Generator) -> Any:
        # 1. Transform parents to normal scores
        z_parents = np.empty(len(parents))
        for i, p in enumerate(parents):
            raw = (float(parent_values[p]) if vt[p] == "continuous"
                   else float(lvl[p].index(parent_values[p])))
            u = _ecdf_transform(sv[p], cu[p], raw)
            z_parents[i] = _norm_ppf(u)

        # 2. Conditional Gaussian draw
        mu_c = float(mu_coefs.dot(z_parents)) if len(z_parents) else 0.0
        z_child = rng.normal(mu_c, sd_cond)

        # 3. Map normal score → uniform → child domain
        u_child = float(np.clip(_norm_cdf(z_child), cu[child][0], cu[child][-1]))
        raw_val = _ecdf_quantile(sv[child], cu[child], u_child)

        if vt[child] == "continuous":
            return float(raw_val)
        else:
            k = len(lvl[child])
            return lvl[child][int(np.clip(round(raw_val), 0, k - 1))]

    parent_types = tuple(vt[p] for p in parents)
    output_type = vt[child]

    return Mechanism(
        name="copula_gaussian",
        fn=fn,
        parent_types=parent_types,
        output_type=output_type,
        spec=None,
    )


def list_copula_families() -> list[str]:
    """List available copula families.

    Always returns ``["gaussian"]`` (built-in); prepends the full
    ``pyvinecopulib`` family list when that package is installed.

    Returns
    -------
    list[str]
    """
    built_in = ["gaussian"]
    try:
        import pyvinecopulib as pv
        extra = [str(f) for f in pv.BicopFamily.__members__]
        return extra + built_in
    except ImportError:
        return built_in
